75	 * upload inserted a fresh row and when it PROMOTED a registry-only row (size 0,
76	 * never hosted-pinned) to a real hosted pin. `promoted` tells compensation to
77	 * revert just the size charge on that pre-existing row rather than delete it.
78	 */
79	interface RegisterOutcome {
80	  cid: string;
81	  size: number;
82	  created: boolean;
83	  promoted: boolean;
84	}
