154	  async upload(accountId: string, bytes: Buffer): Promise<UploadResult> {
155	    // Fail closed on a pool too small (< 2 connections) to host one upload: the
156	    // pin path needs its session-lock connection AND a second for the commit tx,
157	    // so admitting a request here would self-deadlock waiting for the second.
