163	    // ledger below can key on it before any bytes are pinned.
164	    const cid = await this.pinStore.hash(bytes);
165	
166	    // Admit at most `pinSlots` uploads into the session-lock → pin → compensate
167	    // span at once. That span holds a pooled connection across the external pin,
168	    // so an unbounded burst would otherwise exhaust the DB pool; the ceiling
169	    // reserves connections for every other route while the pin is in flight.
