214	
215	  private async registerPin(
216	    manager: EntityManager,
217	    accountId: string,
218	    cid: string,
219	    size: number
220	  ): Promise<RegisterOutcome> {
221	    await setAdvisoryLockTimeout(manager, this.lockTimeoutMs);
222	    // Account key serializes the quota check-then-act; the CID key serializes the
223	    // pin-row insert against a concurrent register/retire of the same CID.
224	    await acquireAdvisoryLocks(manager, [accountLockKey(accountId), advisoryLockKey(cid)]);
